# Откат 2-adresa-razdelov.sh: удаляет записанные адреса разделов, возвращает
# три убранных адреса регистрации с их прежними номерами и удаляет oc_chpu_changes.
# Без этой таблицы пишет STOP и ничего не делает.
( cd /var/www/u2934771/data/www/stroigeroi.ru || exit 1; php -r 'mysqli_report(MYSQLI_REPORT_OFF); include "config.php"; $m = @new mysqli(DB_HOSTNAME, DB_USERNAME, DB_PASSWORD, DB_DATABASE, (int)DB_PORT); if ($m->connect_error) { echo "DB: ", $m->connect_error, "\n"; exit(1); } $m->set_charset("utf8"); $p = DB_PREFIX; if (!$m->query("SELECT 1 FROM {$p}chpu_changes LIMIT 1")) { echo "STOP: no {$p}chpu_changes - nothing to undo\n"; exit(1); } $ok = $m->query("DELETE s FROM {$p}seo_url s JOIN {$p}chpu_changes c ON c.action = \"added\" AND s.store_id = c.store_id AND s.language_id = c.language_id AND s.query = c.query AND s.keyword = c.keyword") && $m->query("INSERT INTO {$p}seo_url (seo_url_id, store_id, language_id, query, keyword) SELECT seo_url_id, store_id, language_id, query, keyword FROM {$p}chpu_changes WHERE action = \"removed\"") && $m->query("DROP TABLE {$p}chpu_changes"); echo $ok ? "undone\n" : "SQL: " . $m->error . "\n";' )
